INSERT INTO feature VALUES('circuit-sites','identity','The site of circuit wirings','univalence-per-stratum','implemented','unique','dependent provers','The carrier''s shapes form a site with a degree and finitely checked generalized Reedy structure, the oracle for the strata univalence certifies. Each wreath level''s Segal certificate is built from the level below, its grounded objects direct with automorphisms, and a shape whose cells meet in a cycle is refused by name.','theory-sites','crates/theory-sites/tests/reedy.rs crates/theory-sites/tests/stratum.rs','crate-tests',NULL);
